    if !drive_letter.is_ascii_alphabetic() || path.chars().nth(path_start) != Some('\\') {
        return None;
    }

    let wsl_path = format!("/mnt/{}{}", drive_letter.to_ascii_lowercase(), &path[path_start..].replace("\\", "/"));
    Some(wsl_path)
