    requirements_toml_file: impl AsRef<Path>,
) -> io::Result<()> {
    // Read the requirements TOML file
    let contents = std::fs::read_to_string(&requirements_toml_file)?;

    // Parse the TOML contents into a `ConfigRequirementsToml` struct
    let requirements: ConfigRequirementsToml = toml::from_str(&contents)?;

    // Convert the file path to an `AbsolutePathBuf`
    let absolute_path = AbsolutePathBuf::from_absolute_path(&requirements_toml_file)?;

    // Define a helper function to apply a requirement if it is set
    fn apply_requirement<T>(
        target: &mut Option<Sourced<T>>,
        source: RequirementSource,
        value: Option<T>,
    ) {
        if let Some(value) = value {
            *target = Some(Sourced {
                value,
                source,
            });
        }
    }

    // Apply the allowed approval policies if they are set
    apply_requirement(
        &mut config_requirements_toml.allowed_approval_policies,
        RequirementSource::SystemRequirementsToml { file: absolute_path.clone() },
        requirements.allowed_approval_policies,
    );

    // Apply the allowed sandbox modes if they are set
    apply_requirement(
        &mut config_requirements_toml.allowed_sandbox_modes,
        RequirementSource::SystemRequirementsToml { file: absolute_path.clone() },
        requirements.allowed_sandbox_modes,
    );

    // Apply the MCP servers if they are set
    apply_requirement(
        &mut config_requirements_toml.mcp_servers,
        RequirementSource::SystemRequirementsToml { file: absolute_path },
        requirements.mcp_servers,
    );

    Ok(())
}

