fn resolve_relative_paths_in_config_toml(
    value_from_config_toml: TomlValue,
    base_dir: &Path,
) -> io::Result<TomlValue> {
    use toml::Value as TomlValue;

    fn resolve_value(value: &TomlValue, base_dir: &Path) -> io::Result<TomlValue> {
        match value {
            TomlValue::String(s) => {
                if let Ok(path) = AbsolutePathBuf::try_from(s) {
                    Ok(TomlValue::String(path.resolve(base_dir).to_string_lossy().into()))
                } else {
                    Ok(value.clone())
                }
            }
            TomlValue::Table(table) => {
                let mut resolved_table = toml::map::Map::new();
                for (key, value) in table {
                    resolved_table.insert(key.clone(), resolve_value(value, base_dir)?);
                }
                Ok(TomlValue::Table(resolved_table))
            }
            TomlValue::Array(array) => {
                let mut resolved_array = Vec::new();
                for value in array {
                    resolved_array.push(resolve_value(value, base_dir)?);
                }
                Ok(TomlValue::Array(resolved_array))
            }
            _ => Ok(value.clone()),
        }
    }

    let resolved_value = resolve_value(&value_from_config_toml, base_dir)?;
    Ok(copy_shape_from_original(&value_from_config_toml, &resolved_value))
}
