    // Clear pending paste placeholders
    self.pending_pastes.clear();

    // Extract placeholder labels from the new text
    let placeholder_labels: HashSet<String> = text
        .split_whitespace()
        .filter_map(|word| {
            if word.starts_with('{') && word.ends_with('}') {
                Some(word[1..word.len() - 1].to_string())
            } else {
                None
            }
        })
        .collect();

    // Retain only attachments whose placeholder labels still appear in the new text
    self.attached_images.retain(|image| {
        placeholder_labels.contains(&image.placeholder_label)
    });

    // Replace the composer content with the new text
    self.textarea.set_text(text);

    // Place the cursor at the end
    self.textarea.move_to_end();

    // Synchronize popups
    self.sync_popups();
}

