use serial_test::serial;
use tempfile::tempdir;
use std::os::unix::fs::PermissionsExt;

/// Write `seed` to a temp file, launch the editor command, and return the updated content.
pub(crate) async fn run_editor(seed: &str, editor_cmd: &[String]) -> Result<String> {
    // Create a temporary file and write the seed content to it
    let mut temp_file = Builder::new().prefix("codex_editor").tempfile()?;
    temp_file.write_all(seed.as_bytes())?;
    temp_file.flush()?;

    // Get the path of the temporary file
    let temp_path = temp_file.path().to_str().ok_or_else(|| Report::msg("Invalid temp file path"))?;

    // Prepare the command to launch the editor
    let mut command = Command::new(&editor_cmd[0]);
    command.args(&editor_cmd[1..]).arg(temp_path);

    // Launch the editor and wait for it to complete
    command.spawn()?.wait().await?;

    // Read the updated content from the temporary file
    let updated_content = fs::read_to_string(temp_path)?;

    Ok(updated_content)
}

