pub fn insert_history_lines<B>(
    terminal: &mut crate::custom_terminal::Terminal<B>,
    lines: Vec<Line>,
) -> io::Result<()>
where
    B: Backend + Write,
{
    let viewport = terminal.viewport_area;
    let mut backend = &mut terminal.backend;

    // Move the scroll region up to accommodate new lines
    queue!(backend, SetScrollRegion(0..viewport.height))?;

    // Insert lines above the viewport
    for line in lines.iter().rev() {
        queue!(backend, MoveTo(0, 0), Clear(ClearType::CurrentLine))?;
        write_spans(backend, line.spans.iter())?;
        queue!(backend, MoveTo(0, 1), Clear(ClearType::FromCursorDown))?;
    }

    // Reset scroll region
    queue!(backend, ResetScrollRegion)?;

    // Redraw the viewport content
    for y in 0..viewport.height {
        let line = &terminal.buffers[terminal.current].lines[viewport.y + y as usize];
        queue!(backend, MoveTo(0, y), Clear(ClearType::CurrentLine))?;
        write_spans(backend, line.spans.iter())?;
    }

    // Move the cursor back to the last known position
    queue!(backend, MoveTo(terminal.last_known_cursor_pos.x, terminal.last_known_cursor_pos.y))?;

    backend.flush()?;

    Ok(())
}

