pub fn insert_history_lines<B>(
    terminal: &mut crate::custom_terminal::Terminal<B>,
    lines: Vec<Line>,
) -> io::Result<()>
where
    B: Backend + Write,
{
    let mut writer = &mut terminal.backend;

    // Move the cursor to the start of the viewport
    queue!(writer, MoveTo(0, terminal.viewport_area.y))?;

    // Clear the area below the viewport
    queue!(writer, Clear(ClearType::FromCursorDown))?;

    // Insert the new lines above the viewport
    for line in lines.iter() {
        write_spans(writer, line.spans.iter())?;
        queue!(writer, MoveToNextLine(1))?;
    }

    // Reset the scroll region to the default
    queue!(writer, ResetScrollRegion)?;

    // Flush the writer to apply changes
    writer.flush()?;

    Ok(())
}

