    text: &str,
    custom_prompts: &[CustomPrompt],
) -> Result<Option<String>, PromptExpansionError> {
    if !text.starts_with("/prompts:") {
        return Ok(None);
    }

    let (name, rest) = parse_slash_name(text).ok_or(PromptExpansionError::Args {
        command: text.to_string(),
        error: PromptArgsError::InvalidCommand,
    })?;

    let prompt = custom_prompts
        .iter()
        .find(|p| p.name == name)
        .ok_or(PromptExpansionError::MissingArgs {
            command: text.to_string(),
            missing: vec![name.to_string()],
        })?;

    let args = parse_prompt_inputs(rest)?;

    let mut expanded = prompt.content.clone();

    for (key, value) in &args {
        expanded = expanded.replace(&format!("${{{}}}", key), value);
    }

    let positional_args: Vec<String> = args.values().cloned().collect();
    expanded = expand_numeric_placeholders(&expanded, &positional_args);

    Ok(Some(expanded))
}
