pub(crate) fn display_path_for(path: &Path, cwd: &Path) -> String {
    if path.is_relative() {
        return path.display().to_string();
    }

    if let Some(home_relative) = relativize_to_home(path) {
        return format!("~/{home_relative.display()}");
    }

    if let Some(repo_root) = get_git_repo_root(path) {
        if let Ok(rel_path) = path.strip_prefix(&repo_root) {
            return format!(".git/{}", rel_path.display());
        }
    }

    if let Ok(rel_path) = path.strip_prefix(cwd) {
        return rel_path.display().to_string();
    }

    path.display().to_string()
}
