use serde_json::{Value, Error};

pub(crate) fn format_json_compact(text: &str) -> Option<String> {
    match text.parse::<Value>() {
        Ok(json_value) => {
            let mut result = String::new();
            format_json_value(&json_value, &mut result);
            Some(result)
        }
        Err(_) => None,
    }
}

fn format_json_value(value: &Value, result: &mut String) {
    match value {
        Value::Object(obj) => {
            result.push('{');
            let mut first = true;
            for (key, val) in obj {
                if !first {
                    result.push_str(", ");
                }
                first = false;
                result.push_str(&format!("\"{}\": ", key));
                format_json_value(val, result);
            }
            result.push('}');
        }
        Value::Array(arr) => {
            result.push('[');
            let mut first = true;
            for val in arr {
                if !first {
                    result.push_str(", ");
                }
                first = false;
                format_json_value(val, result);
            }
            result.push(']');
        }
        Value::String(s) => {
            result.push_str(&format!("\"{}\"", s));
        }
        Value::Number(n) => {
            result.push_str(&n.to_string());
        }
        Value::Bool(b) => {
            result.push_str(&b.to_string());
        }
        Value::Null => {
            result.push_str("null");
        }
