fn format_json_value(value: &Value, result: &mut String) {
    match value {
        Value::Object(obj) => {
            result.push('{');
            let mut first = true;
            for (key, val) in obj {
                if !first {
                    result.push_str(", ");
                }
                first = false;
                result.push_str(&format!("\"{}\": ", key));
                format_json_value(val, result);
            }
            result.push('}');
        }
        Value::Array(arr) => {
            result.push('[');
            let mut first = true;
            for val in arr {
                if !first {
                    result.push_str(", ");
                }
                first = false;
                format_json_value(val, result);
