                TomlValue::Float(n.as_f64().unwrap())
            } else {
                panic!("Unsupported number type")
            }
        }
        JsonValue::String(s) => TomlValue::String(s),
        JsonValue::Array(a) => TomlValue::Array(a.into_iter().map(json_to_toml).collect()),
        JsonValue::Object(o) => {
            let mut toml_map = toml::map::Map::new();
            for (key, value) in o {
                toml_map.insert(key, json_to_toml(value));
            }
            TomlValue::Table(toml_map)
        }
    }
}
